<script setup lang="ts">
import { Archive, ArrowDownToLine, ArrowLeft, ArrowRight, BookOpen, Check, CheckCircle2, ChevronRight, CircleHelp, ExternalLink, FilePenLine, FileText, FolderOpen, Gamepad2, Globe2, ImagePlus, Images, Info, Landmark, LayoutDashboard, LibraryBig, LoaderCircle, LogOut, MapPin, PenLine, Plus, Search, Settings2, ShieldCheck, Sparkles, UsersRound, Video, X } from 'lucide-vue-next'
import { contentSections, fieldLabels, newContent, type CmsKind } from '~/shared/cmsEditor'
const { user, refresh, logout } = useAuth()
const allowed = computed(() => user.value?.role === 'ADMIN' || user.value?.role === 'EDITOR')
const ready = ref(false)
const active = ref<'overview'|'content'|'media'|'users'|'help'>('overview')
const kind = ref<CmsKind>('ARTICLE')
const overview = ref<any>(null)
const items = ref<any[]>([]), total = ref(0), page = ref(1), query = ref(''), status = ref('')
const loading = ref(false), saving = ref(false), notice = ref(''), error = ref('')
const editing = ref<any>(null), dirty = ref(false), editorInstance = ref(0)
const users = ref<any[]>([]), userPage = ref(1), userLoading = ref(false)
const media = ref<any[]>([]), mediaTotal = ref(0), mediaPage = ref(1), mediaQuery = ref(''), mediaLoading = ref(false)
const mediaForm = ref({ url:'', alt:'', credit:'', license:'', sourceUrl:'' }), editingMedia = ref<string|null>(null), showMediaForm = ref(false), mediaFormElement = ref<HTMLFormElement>()
const confirmDialog = ref<HTMLDialogElement>(), pendingNavigation = ref<(()=>void)|null>(null)
const copied = ref('')
const icons:Record<string,any> = {BookOpen,Sparkles,UsersRound,Landmark,Gamepad2,Video,FolderOpen,PenLine,MapPin,LibraryBig,FileText,Settings2}
const groups = [...new Set(contentSections.map(x=>x.group))]
const section = computed(()=>contentSections.find(x=>x.kind===kind.value)!)
const statusLabels:Record<string,string> = {DRAFT:'Սևագիր',PUBLISHED:'Հրապարակված',ARCHIVED:'Արխիվացված'}
const counts = computed(()=>{
 const result={all:0,published:0,drafts:0,archived:0}
 for(const row of overview.value?.groups||[]){result.all+=row._count._all;if(row.status==='PUBLISHED')result.published+=row._count._all;if(row.status==='DRAFT')result.drafts+=row._count._all;if(row.status==='ARCHIVED')result.archived+=row._count._all}
 return result
})
function sectionCount(value:CmsKind){return (overview.value?.groups||[]).filter((x:any)=>x.kind===value).reduce((sum:number,x:any)=>sum+x._count._all,0)}
function formatDate(value:string){return new Intl.DateTimeFormat('en-GB',{timeZone:'Asia/Yerevan',day:'2-digit',month:'2-digit',year:'numeric'}).format(new Date(value)).replaceAll('/','.')}
function report(e:any){error.value=e.data?.statusMessage||'Չհաջողվեց բեռնել տվյալները։ Ստուգիր կապը և փորձիր կրկին։';notice.value=''}
function navigate(change:()=>void){if(dirty.value){pendingNavigation.value=change;confirmDialog.value?.showModal()}else change()}
function discard(){dirty.value=false;confirmDialog.value?.close();const change=pendingNavigation.value;pendingNavigation.value=null;change?.()}
function switchView(value:typeof active.value){navigate(()=>{active.value=value;editing.value=null;notice.value='';error.value='';if(value==='overview')void loadOverview();if(value==='media')void loadMedia();if(value==='users')void loadUsers()})}
function selectSection(value:CmsKind){navigate(()=>{kind.value=value;active.value='content';editing.value=null;page.value=1;query.value='';status.value='';notice.value='';error.value='';void loadContent()})}
async function loadOverview(){try{overview.value=await $fetch('/api/admin/overview')}catch(e){report(e)}}
let listRequest=0
async function loadContent(){const ticket=++listRequest;loading.value=true;error.value='';try{const result=await $fetch<any>('/api/admin/content',{query:{kind:kind.value,page:page.value,q:query.value,...(status.value?{status:status.value}:{})}});if(ticket!==listRequest)return;items.value=result.items;total.value=result.total}catch(e){if(ticket===listRequest)report(e)}finally{if(ticket===listRequest)loading.value=false}}
function create(value:CmsKind=kind.value){navigate(()=>{kind.value=value;active.value='content';editing.value=newContent(value);editorInstance.value++;notice.value='';error.value='';window.scrollTo({top:90,behavior:'smooth'})})}
async function openEditor(id:string,value:CmsKind=kind.value){navigate(()=>{void fetchEditor(id,value)})}
async function fetchEditor(id:string,value:CmsKind){loading.value=true;error.value='';try{const record=await $fetch('/api/admin/content',{query:{id}});kind.value=value;active.value='content';editing.value=record;editorInstance.value++;window.scrollTo({top:90,behavior:'smooth'})}catch(e){report(e)}finally{loading.value=false}}
function closeEditor(){navigate(()=>{editing.value=null;dirty.value=false;void loadContent()})}
function deleted(){dirty.value=false;editing.value=null;page.value=1;notice.value='Նյութն անվերադարձ ջնջված է։';void loadContent();void loadOverview()}
function saved(record:any){dirty.value=false;editing.value=record;void loadOverview()}
async function loadUsers(){userLoading.value=true;error.value='';try{users.value=(await $fetch<any>('/api/admin/users',{query:{page:userPage.value}})).items}catch(e){report(e)}finally{userLoading.value=false}}
async function updateUser(item:any){saving.value=true;error.value='';try{await $fetch('/api/admin/users',{method:'PUT',body:{id:item.id,role:item.role,disabled:item.disabled}});notice.value='Օգտատիրոջ իրավունքները պահպանված են։'}catch(e){report(e);await loadUsers()}finally{saving.value=false}}
async function loadMedia(){mediaLoading.value=true;error.value='';try{const result=await $fetch<any>('/api/admin/media',{query:{page:mediaPage.value,q:mediaQuery.value}});media.value=result.items;mediaTotal.value=result.total}catch(e){report(e)}finally{mediaLoading.value=false}}
function newMedia(){editingMedia.value=null;mediaForm.value={url:'',alt:'',credit:'',license:'',sourceUrl:''};showMediaForm.value=true;notice.value='';error.value=''}
function imageSelected(item:any){if(item&&!editingMedia.value){editingMedia.value=item.id;mediaForm.value.alt ||= item.alt;mediaForm.value.credit ||= item.credit;mediaForm.value.license ||= item.license;mediaForm.value.sourceUrl ||= item.sourceUrl}}
function editMedia(item:any){editingMedia.value=item.id;mediaForm.value={url:item.url,alt:item.alt,credit:item.credit,license:item.license,sourceUrl:item.sourceUrl};showMediaForm.value=true;window.scrollTo({top:100,behavior:'smooth'})}
async function saveMedia(){saving.value=true;error.value='';try{await $fetch('/api/admin/media',{method:editingMedia.value?'PUT':'POST',query:editingMedia.value?{id:editingMedia.value}:{},body:mediaForm.value});showMediaForm.value=false;notice.value='Նկարի տվյալները պահպանված են։ Այժմ այն կարող ես ընտրել նյութի խմբագրման ընթացքում։';await loadMedia();void loadOverview()}catch(e){report(e)}finally{saving.value=false}}
async function removeMedia(id:string){if(!confirm('Հեռացնե՞լ նկարը ցանկից։ Արդեն նյութերում օգտագործվող նկարի հղումը կշարունակի աշխատել։'))return;try{await $fetch('/api/admin/media',{method:'DELETE',query:{id}});await loadMedia();notice.value='Նկարը հեռացվեց մեդիայի ցանկից։'}catch(e){report(e)}}
async function copyImage(url:string){try{await navigator.clipboard.writeText(url);copied.value=url;setTimeout(()=>{if(copied.value===url)copied.value=''},2500)}catch{error.value='Հղումը չպատճենվեց։ Կարող ես այն ընտրել նկարի դաշտից։'}}
async function signOut(){navigate(()=>{void logout().then(()=>{void navigateTo('/login')}).catch(report)})}
function beforeUnload(event:BeforeUnloadEvent){if(dirty.value){event.preventDefault();event.returnValue=''}}
onBeforeRouteLeave(()=>!dirty.value||confirm('Նյութում կան չպահպանված փոփոխություններ։ Դո՞ւրս գալ՝ առանց դրանք պահպանելու։'))
onMounted(async()=>{window.addEventListener('beforeunload',beforeUnload);try{await refresh();if(!allowed.value){await navigateTo('/login');return}await loadOverview()}catch(e){report(e)}finally{ready.value=true}})
onBeforeUnmount(()=>{listRequest++;window.removeEventListener('beforeunload',beforeUnload)})
useHead({title:'Կառավարման վահանակ — FACTUM',meta:[{name:'robots',content:'noindex,nofollow'}]})
</script>

<template>
  <main class="cms-page">
    <template v-if="allowed">
      <div class="cms-frame">
        <aside class="cms-navigation">
          <div class="cms-brand"><span><Sparkles :size="20"/></span><div><strong>FACTUM</strong><small>ԲՈՎԱՆԴԱԿՈՒԹՅԱՆ ԿԱՌԱՎԱՐՈՒՄ</small></div></div>
          <nav aria-label="Կառավարման բաժիններ">
            <button class="nav-item" :class="{selected:active==='overview'}" @click="switchView('overview')"><LayoutDashboard :size="18"/><span>Ընդհանուր պատկեր</span></button>
            <div v-for="group in groups" :key="group" class="nav-group"><p>{{group}}</p><button v-for="item in contentSections.filter(x=>x.group===group)" :key="item.kind" class="nav-item" :class="{selected:active==='content'&&kind===item.kind}" @click="selectSection(item.kind)"><component :is="icons[item.icon]" :size="17"/><span>{{item.label}}</span><small v-if="overview">{{sectionCount(item.kind)}}</small></button></div>
            <div class="nav-group"><p>Քո աշխատանքային միջավայրը</p><button class="nav-item" :class="{selected:active==='media'}" @click="switchView('media')"><Images :size="17"/><span>Նկարների պահոց</span><small v-if="overview">{{overview.media}}</small></button><button v-if="user?.role==='ADMIN'" class="nav-item" :class="{selected:active==='users'}" @click="switchView('users')"><ShieldCheck :size="17"/><span>Օգտատերեր</span></button><button class="nav-item" :class="{selected:active==='help'}" @click="switchView('help')"><CircleHelp :size="17"/><span>Ինչպե՞ս օգտվել</span></button></div>
          </nav>
          <div class="navigation-help"><span><BookOpen :size="18"/></span><p>Առաջի՞ն անգամ ես այստեղ։<button @click="switchView('help')">Տես նյութ ավելացնելու քայլերը <ArrowRight :size="12"/></button></p></div>
          <div class="cms-account"><span class="account-avatar">{{user?.name?.slice(0,1)}}</span><div><strong>{{user?.name}}</strong><small>{{user?.role==='ADMIN'?'Ադմինիստրատոր':'Խմբագիր'}}</small></div><button aria-label="Դուրս գալ հաշվից" title="Դուրս գալ" @click="signOut"><LogOut :size="17"/></button></div>
        </aside>

        <div class="cms-workspace">
          <header class="workspace-bar"><div class="breadcrumb"><span>Կառավարման վահանակ</span><ChevronRight :size="13"/><strong>{{active==='overview'?'Ընդհանուր պատկեր':active==='content'?section.label:active==='media'?'Նկարների պահոց':active==='users'?'Օգտատերեր':'Օգնություն'}}</strong></div><a href="/" target="_blank" rel="noopener" class="visit-site"><Globe2 :size="15"/>Դիտել կայքը<ExternalLink :size="12"/></a></header>
          <div class="workspace-content">
            <div v-if="notice" class="cms-notice" role="status"><CheckCircle2 :size="18"/><p>{{notice}}</p><button aria-label="Փակել հաղորդագրությունը" @click="notice=''"><X :size="16"/></button></div>
            <div v-if="error" class="cms-error" role="alert"><p>{{error}}</p><button @click="error=''" aria-label="Փակել սխալը"><X :size="16"/></button></div>

            <template v-if="active==='overview'">
              <header class="page-title"><div><p class="eyebrow">ՔՈ FACTUM ԱՇԽԱՏԱՆՔԱՅԻՆ ՏԱՐԱԾՔԸ</p><h1>Բարի գալուստ, {{user?.name}}<span class="welcome-dot">✦</span></h1><p>Այստեղ կարող ես ավելացնել, խմբագրել և հրապարակել կայքի նյութերը։</p></div><button class="primary-button" @click="create('ARTICLE')"><Plus :size="17"/>Ավելացնել հոդված</button></header>
              <div class="overview-stats"><div class="stat-card"><span class="stat-icon"><FileText :size="20"/></span><p>Բոլոր նյութերը<strong>{{overview?counts.all.toLocaleString('hy-AM'):'—'}}</strong></p></div><div class="stat-card"><span class="stat-icon green"><Globe2 :size="20"/></span><p>Հրապարակված<strong>{{overview?counts.published.toLocaleString('hy-AM'):'—'}}</strong></p></div><div class="stat-card"><span class="stat-icon gold"><FilePenLine :size="20"/></span><p>Սևագրեր<strong>{{overview?counts.drafts.toLocaleString('hy-AM'):'—'}}</strong></p></div><div class="stat-card"><span class="stat-icon purple"><Images :size="20"/></span><p>Պահոցի նկարներ<strong>{{overview?overview.media:'—'}}</strong></p></div></div>
              <section class="start-banner"><div class="start-symbol"><Sparkles :size="27"/></div><div><p class="eyebrow">ՍԿՍԻՐ ԱՅՍՏԵՂԻՑ</p><h2>Նոր տեղեկություն ավելացնենք կայք</h2><p>Ընտրիր նյութի տեսակը, լրացրու դաշտերը, ստուգիր և հրապարակիր։</p></div><button class="quiet-button" @click="switchView('help')">Տես քայլերը <ArrowRight :size="15"/></button></section>
              <div class="section-heading"><h2>Ի՞նչ ես ցանկանում ավելացնել</h2><span>Ընտրիր համապատասխան բաժինը</span></div>
              <div class="quick-create-grid"><button v-for="item in contentSections.filter(x=>x.group==='Հիմնական բովանդակություն')" :key="item.kind" class="quick-create-card" @click="create(item.kind)"><span class="quick-icon"><component :is="icons[item.icon]" :size="23"/></span><strong>{{item.label}}</strong><p>{{item.description}}</p><span class="quick-create-link">Ավելացնել {{item.singular}}<Plus :size="14"/></span></button></div>
              <section class="cms-panel recent-panel"><div class="panel-title"><div><h2>Վերջին փոփոխությունները</h2><p>Վերադարձիր այն նյութին, որի վրա վերջերս աշխատել ես։</p></div><FilePenLine :size="21"/></div><div v-if="!overview" class="loading-state"><LoaderCircle :size="20"/>Բեռնվում է…</div><p v-else-if="!overview.recent.length" class="empty-caption">Քո առաջին նյութը կարող ես ավելացնել վերևի բաժիններից։</p><button v-for="item in overview?.recent||[]" :key="item.id" class="recent-row" @click="openEditor(item.id,item.kind)"><span class="row-icon"><component :is="icons[contentSections.find(x=>x.kind===item.kind)?.icon||'FileText']" :size="18"/></span><span class="recent-title"><strong>{{item.title}}</strong><small>{{contentSections.find(x=>x.kind===item.kind)?.label}} · {{formatDate(item.updatedAt)}}</small></span><span class="status-badge" :class="item.status.toLowerCase()">{{statusLabels[item.status]}}</span><ChevronRight :size="15"/></button></section>
            </template>

            <template v-if="active==='content'">
              <LazyAdminContentEditor v-if="editing" :key="editorInstance" :record="editing" @close="closeEditor" @saved="saved" @deleted="deleted" @dirty="dirty=$event"/>
              <template v-else>
                <header class="page-title"><div><p class="eyebrow">ԲՈՎԱՆԴԱԿՈՒԹՅՈՒՆ</p><h1>{{section.label}}</h1><p>{{section.description}}</p></div><button class="primary-button" @click="create()"><Plus :size="17"/>Ավելացնել {{section.singular}}</button></header>
                <div class="list-guidance"><Info :size="17"/><p>Բացիր նյութը՝ խմբագրելու համար։ <strong>Սևագիրը</strong> չի երևում այցելուներին, իսկ <strong>հրապարակված</strong> նյութը հասանելի է կայքում։</p></div>
                <section class="cms-panel content-list"><form class="list-tools" @submit.prevent="page=1;loadContent()"><div class="search-field"><Search :size="18"/><input v-model="query" type="search" placeholder="Որոնիր նյութի վերնագրով…" aria-label="Որոնել նյութերը"><button type="submit">Որոնել</button></div><select v-model="status" aria-label="Նյութի կարգավիճակ" @change="page=1;loadContent()"><option value="">Բոլոր նյութերը</option><option value="PUBLISHED">Հրապարակված</option><option value="DRAFT">Սևագրեր</option><option value="ARCHIVED">Արխիվացված</option></select></form>
                  <div class="list-summary"><span>{{total}} {{section.singular}}</span><span>Կարգավիճակ · Վերջին փոփոխություն</span></div>
                  <div v-if="loading" class="loading-state"><LoaderCircle :size="20"/>Նյութերը բեռնվում են…</div>
                  <div v-else-if="!items.length" class="empty-state"><span><component :is="icons[section.icon]" :size="30"/></span><h2>{{query||status?'Նյութ չի գտնվել':'Այս բաժնում դեռ նյութ չկա'}}</h2><p>{{query||status?'Փորձիր այլ բառ կամ փոխիր ընտրված կարգավիճակը։':'Սկսիր առաջին նյութից․ լրացրու դաշտերը և պահպանիր կամ հրապարակիր։'}}</p><button v-if="query||status" class="secondary-button" @click="query='';status='';page=1;loadContent()">Մաքրել որոնումը</button><button v-else class="primary-button" @click="create()"><Plus :size="16"/>Ավելացնել {{section.singular}}</button></div>
                  <button v-for="item in loading?[]:items" :key="item.id" class="content-row" @click="openEditor(item.id)"><span class="row-icon"><component :is="icons[section.icon]" :size="19"/></span><span class="content-row-title"><strong>{{item.title}}</strong><small>Բացել և խմբագրել</small></span><span class="status-badge" :class="item.status.toLowerCase()">{{statusLabels[item.status]}}</span><time :datetime="item.updatedAt">{{formatDate(item.updatedAt)}}</time><span class="edit-row-button"><PenLine :size="15"/><span>Խմբագրել</span></span></button>
                  <footer class="pagination"><button :disabled="page<=1||loading" @click="page--;loadContent()"><ArrowLeft :size="14"/>Նախորդ</button><span>Էջ {{page}} / {{Math.max(1,Math.ceil(total/25))}}</span><button :disabled="page*25>=total||loading" @click="page++;loadContent()">Հաջորդ<ArrowRight :size="14"/></button></footer>
                </section>
              </template>
            </template>

            <template v-if="active==='media'">
              <header class="page-title"><div><p class="eyebrow">ՔՈ ՄԵԴԻԱՅԻ ՊԱՀՈՑԸ</p><h1>Նկարներ՝ քո նյութերի համար</h1><p>Ավելացրու նկարները մեկ անգամ և ընտրիր դրանք նյութը խմբագրելիս։</p></div><button class="primary-button" @click="newMedia"><Plus :size="17"/>Ավելացնել նկար</button></header>
              <section v-if="showMediaForm" class="cms-panel media-form-panel"><div class="panel-title"><div><h2>{{editingMedia?'Խմբագրել նկարի տվյալները':'Նոր նկար'}}</h2><p>Ընտրիր կամ վերբեռնիր նկարը և նշիր՝ ինչ է պատկերված։</p></div><button @click="showMediaForm=false" aria-label="Փակել նկարի ձևը"><X :size="20"/></button></div><form ref="mediaFormElement" class="media-editor" @submit.prevent="saveMedia"><div><label class="input-label">Նկար <span>*</span></label><AdminImageField v-model="mediaForm.url" label="Նկարի նախադիտում" @selected="imageSelected"/><input v-model="mediaForm.url" class="media-url-check" required aria-label="Ընտրված նկարի հղումը" placeholder="Նկարի հղումը լրացվում է ընտրությունից հետո"></div><div class="media-metadata"><label>Նկարի նկարագրություն <span>*</span><input v-model="mediaForm.alt" required maxlength="500" placeholder="Օրինակ՝ Արարատ լեռը մայրամուտին"><small>Այս տեքստը նաև օգնում է նկարը տեսնելու հնարավորություն չունեցող այցելուներին։</small></label><label>Նկարի հեղինակ կամ աղբյուր<input v-model="mediaForm.credit" maxlength="500" placeholder="Լուսանկարչի անունը կամ աղբյուրը"></label><label>Օգտագործման արտոնագիր<input v-model="mediaForm.license" maxlength="500" placeholder="Օրինակ՝ սեփական լուսանկար կամ CC BY-SA 4.0"></label><label>Սկզբնական աղբյուրի հղում<input v-model="mediaForm.sourceUrl" type="url" placeholder="https://…"></label></div><div class="media-form-actions"><button type="button" class="secondary-button" @click="showMediaForm=false">Չեղարկել</button><button class="primary-button" :disabled="saving"><Check :size="16"/>{{saving?'Պահպանվում է…':'Պահպանել նկարը'}}</button></div></form></section>
              <form class="media-search" @submit.prevent="mediaPage=1;loadMedia()"><div class="search-field"><Search :size="17"/><input v-model="mediaQuery" type="search" placeholder="Որոնիր նկարի նկարագրությամբ…" aria-label="Որոնել նկարները"><button>Որոնել</button></div><span>{{mediaTotal}} նկար</span></form><div v-if="mediaLoading" class="loading-state"><LoaderCircle :size="20"/>Նկարները բեռնվում են…</div><div v-else-if="!media.length" class="cms-panel empty-state"><span><Images :size="32"/></span><h2>{{mediaQuery?'Նկար չի գտնվել':'Նկարների պահոցը դեռ դատարկ է'}}</h2><p>Ավելացրու նոր նկար կամ ընտրիր այն անմիջապես նյութի խմբագրման ձևից։</p><button class="primary-button" @click="newMedia"><Plus :size="16"/>Ավելացնել նկար</button></div><div v-else class="media-grid"><figure v-for="item in media" :key="item.id" class="media-card"><div class="media-photo"><img :src="item.url" :alt="item.alt" loading="lazy" width="320" height="200"></div><figcaption><strong>{{item.alt}}</strong><p>{{item.credit||'Հեղինակը նշված չէ'}}<span v-if="item.license"> · {{item.license}}</span></p><div class="media-card-actions"><button @click="editMedia(item)"><PenLine :size="14"/>Խմբագրել</button><button @click="copyImage(item.url)"><Check v-if="copied===item.url" :size="14"/><ExternalLink v-else :size="14"/>{{copied===item.url?'Պատճենված է':'Հղումը'}}</button></div><button v-if="user?.role==='ADMIN'" class="remove-media" @click="removeMedia(item.id)">Հեռացնել պահոցի ցանկից</button></figcaption></figure></div><footer class="pagination"><button :disabled="mediaPage<=1||mediaLoading" @click="mediaPage--;loadMedia()"><ArrowLeft :size="14"/>Նախորդ</button><span>Էջ {{mediaPage}} / {{Math.max(1,Math.ceil(mediaTotal/25))}}</span><button :disabled="mediaPage*25>=mediaTotal||mediaLoading" @click="mediaPage++;loadMedia()">Հաջորդ<ArrowRight :size="14"/></button></footer>
            </template>

            <template v-if="active==='users'&&user?.role==='ADMIN'">
              <header class="page-title"><div><p class="eyebrow">ՄԱՐԴԻԿ ԵՎ ԻՐԱՎՈՒՆՔՆԵՐ</p><h1>Օգտատերեր</h1><p>Ընտրիր՝ ով կարող է խմբագրել կայքը և ով է պարզապես օգտվում իր անձնական հաշվից։</p></div></header><div class="role-explainer"><p><strong>Ադմինիստրատոր</strong>Կառավարում է նյութերն ու օգտատերերին։</p><p><strong>Խմբագիր</strong>Ավելացնում, խմբագրում և հրապարակում է նյութեր։</p><p><strong>Օգտատեր</strong>Պահպանում է նյութեր իր «Իմ FACTUM»-ում։</p></div><section class="cms-panel"><div v-if="userLoading" class="loading-state"><LoaderCircle :size="20"/>Բեռնվում է…</div><div v-for="item in userLoading?[]:users" :key="item.id" class="user-row"><span class="account-avatar">{{item.name?.slice(0,1)}}</span><div class="user-identity"><strong>{{item.name}}<small v-if="item.id===user?.id">Սա դու ես</small></strong><span>{{item.email}}</span></div><select v-model="item.role" :disabled="item.id===user?.id||saving" :aria-label="`${item.name}․ դերը`"><option value="ADMIN">Ադմինիստրատոր</option><option value="EDITOR">Խմբագիր</option><option value="USER">Օգտատեր</option></select><label class="block-user"><input v-model="item.disabled" type="checkbox" :disabled="item.id===user?.id||saving">Արգելափակված</label><button class="secondary-button" :disabled="item.id===user?.id||saving" @click="updateUser(item)">Պահպանել</button></div><footer class="pagination"><button :disabled="userPage===1||userLoading" @click="userPage--;loadUsers()"><ArrowLeft :size="14"/>Նախորդ</button><span>Էջ {{userPage}}</span><button :disabled="users.length<25||userLoading" @click="userPage++;loadUsers()">Հաջորդ<ArrowRight :size="14"/></button></footer></section>
            </template>

            <template v-if="active==='help'">
              <header class="page-title"><div><p class="eyebrow">ՔՈ ՓՈՔՐ ՈՒՂԵՑՈՒՅՑԸ</p><h1>Կայքը լրացնելը՝ պարզ քայլերով</h1><p>Ծրագրային կոդ գրել պետք չէ։ Ընտրիր բաժինը և լրացրու քեզ ծանոթ դաշտերը։</p></div></header><div class="help-steps"><article><span>01</span><h2>Ընտրիր նյութի տեսակը</h2><p>Ձախ ցանկից բացիր բաժինը։ Օրինակ՝ «Հոդվածներ»՝ հանրագիտարանի համար, «Հետաքրքիր փաստեր»՝ կարճ փաստերի համար։ Սեղմիր «Ավելացնել»։</p></article><article><span>02</span><h2>Լրացրու տեղեկությունները</h2><p>Գրիր վերնագիրը, ընտրիր թեման և լրացրու տեքստը։ Անհրաժեշտ դաշտերը նշված են աստղանիշով։ Նկար ընտրելու համար սեղմիր նկարի դաշտի կոճակը։</p></article><article><span>03</span><h2>Ստուգիր և հրապարակիր</h2><p>Սեղմիր «Նախադիտել նյութը», ստուգիր տեքստն ու աղբյուրը, ապա՝ «Հրապարակել կայքում»։ Փոփոխությունը կայքում կարող է երևալ մինչև 30 վայրկյանում։</p></article></div><section class="cms-panel help-topics"><h2>Հաճախ պետք եկող տեղեկություններ</h2><details open><summary>Ո՞րն է սևագրի և հրապարակված նյութի տարբերությունը</summary><p>Սևագիրը քո աշխատանքային տարբերակն է, որը այցելուները չեն տեսնում։ Եթե խմբագրում ես արդեն հրապարակված նյութը և պահպանում սևագիր, կայքում մնում է դրա նախկին հրապարակված տարբերակը։ Նորը տեսանելի կլինի միայն «Հրապարակել կայքում» սեղմելուց հետո։</p></details><details><summary>Ինչպե՞ս փոխել գործող նյութը</summary><p>Բացիր համապատասխան բաժինը, որոնիր նյութը վերնագրով և սեղմիր դրա վրա։ Փոփոխիր դաշտերը, նախադիտիր և նորից հրապարակիր։ Եթե նյութը միաժամանակ ուրիշն էլ է փոփոխել, CMS-ը կզգուշացնի՝ փոփոխությունները չկորցնելու համար։</p></details><details><summary>Ինչպե՞ս ավելացնել խաղի հարց</summary><p>Բացիր «Խաղերի հարցեր» բաժինը և ընտրիր խաղն ու բարդությունը։ Լրացրու հարցը և պատասխանները։ Ճիշտ պատասխանը նշիր առաջարկվող տարբերակներից մեկի կողքին։ «Ճիշտ / սխալ» խաղում պարզապես նշիր՝ պնդումը ճիշտ է, թե սխալ։ Ավելացրու նաև բացատրություն։</p></details><details><summary>Ինչպե՞ս օգտագործել նկարները</summary><p>Նյութի նկարի դաշտից կարող ես ընտրել պահոցի նկարը, վերբեռնել նորը կամ տեղադրել արդեն հասանելի նկարի հղումը։ Եթե վերբեռնումը դեռ միացված չէ, CMS-ը այդ մասին կհայտնի․ այդ դեպքում կարող ես օգտագործել հղումը։ Նշիր նկարի հեղինակին և օգտագործման արտոնագիրը։</p></details><details><summary>Ինչպե՞ս անվերադարձ ջնջել նյութը</summary><p>Բացիր նյութը և ընտրիր «Ջնջել անվերադարձ»։ Հաստատման պատուհանում մուտքագրիր նյութի ամբողջական անվանումը։ Գործողությունը հասանելի է միայն ադմինիստրատորին և CMS-ից չի վերականգնվում։ Նկարների ֆայլերն ու առանձին կապված նյութերը պահպանվում են։ Ժամանակավոր հեռացման համար ընտրիր արխիվացումը։</p></details><details><summary>Ինչպե՞ս ժամանակավորապես հեռացնել նյութը</summary><p>Բացիր նյութը և սեղմիր «Տեղափոխել արխիվ»։ Այն կպահպանվի CMS-ում, բայց այլևս չի երևա կայքում։ Հետագայում այն կարող ես գտնել «Արխիվացված» ֆիլտրով և կրկին հրապարակել։</p></details><details><summary>Ինչպե՞ս լրացնել մարդու կենսագրությունը</summary><p>Բացիր «Հայտնի մարդիկ», գրիր անունը, կյանքի տարեթվերը և գործունեությունը, ավելացրու դիմանկարը։ Կենսագրությունը կարող ես բաժանել մասերի։ Ստուգիր նաև տվյալ մարդուն նվիրված հուշարձանները և դրանք առանձին ավելացրու «Հուշարձաններ» բաժնում՝ աղբյուրներով ու լուսանկարներով։ Գործող ստեղծագործությունների հերթականությունը մի փոխիր։</p></details><details><summary>Ինչպե՞ս խմբագրել «Մեր մասին» էջը</summary><p>Բացիր «Կայքի էջեր» բաժինը, ավելացրու նոր էջ և «Որտե՞ղ ցուցադրել» դաշտում ընտրիր «Մեր մասին»։ Նույն կերպ կարող ես լրացնել «Աջակցիր FACTUM-ին» էջը։ Եթե այդ էջն արդեն ստեղծված է, խմբագրիր գործող նյութը։</p></details></section><button class="primary-button help-start" @click="create('ARTICLE')"><Plus :size="17"/>Ավելացնել առաջին հոդվածը</button>
            </template>
          </div>
        </div>
      </div>
      <dialog ref="confirmDialog" class="unsaved-dialog"><div><span class="dialog-symbol"><FilePenLine :size="28"/></span><h2>Փոփոխությունները դեռ չեն պահպանվել</h2><p>Եթե հիմա դուրս գաս, վերջին փոփոխությունները կկորչեն։ Կարող ես վերադառնալ նյութին և սեղմել «Պահպանել սևագիր»։</p><div><button class="primary-button" @click="confirmDialog?.close();pendingNavigation=null">Շարունակել խմբագրումը</button><button class="discard-button" @click="discard">Դուրս գալ առանց պահպանելու</button></div></div></dialog>
    </template>
    <div v-else class="cms-access-state"><span class="access-symbol"><ShieldCheck :size="30"/></span><h1>{{ready?'Մուտք գործիր կառավարման վահանակ':'Ստուգվում է մուտքի իրավունքը'}}</h1><p v-if="error" role="alert">{{error}}</p><NuxtLink v-if="ready" to="/login" class="primary-button">Մուտք գործել <ArrowRight :size="16"/></NuxtLink><LoaderCircle v-else class="spinning" :size="22"/></div>
  </main>
